do $$declare x jsonb;f uuid;q jsonb:='{"reporting_version":3}';h jsonb;s jsonb;row jsonb;c jsonb;seen uuid[]:='{}';v jsonb;n integer:=0;before_digest text;legacy jsonb;begin
 select t.x into x from reporting_test.context t;f:=(x->>'factory')::uuid;perform set_config('request.jwt.claim.sub',x->>'owner',false);
 legacy:=public.production_history(f);
 perform reporting_test.ok(legacy=private.production_history_before_m3a(f,'{}','date','desc',1),'legacy contract unchanged');
 h:=public.production_history(f,q);
 perform reporting_test.ok(h->>'contract_version'='3' and h->>'time_basis'='recorded','opt-in recorded default');
 perform reporting_test.ok((h->>'total')::int=(select count(*) from public.production_entries where factory_id=f),'complete entry count');
 perform reporting_test.ok(exists(select 1 from jsonb_array_elements(h->'rows')r where r->>'recording_kind'='ACTIVE_ORDINARY'),'active declaration history');
 perform reporting_test.ok(exists(select 1 from jsonb_array_elements(h->'rows')r where r->>'recording_kind'='LATE_ORDINARY' and r->>'current_item_status'='completed'),'late declaration preserves completion');
 perform reporting_test.ok(not exists(select 1 from jsonb_array_elements(h->'rows')r where r->>'time_precision'<>'SHIFT_PERIOD'),'V3 period precision');
 select r into row from jsonb_array_elements(h->'rows')r where r->>'id'=x->>'unreviewed';
 perform reporting_test.ok(row#>>'{observation,status}'='PENDING' and row#>>'{lean_evidence,reviewed_scrap_kg}' is null,'unreviewed Scrap not approved evidence');
 select r into row from jsonb_array_elements(h->'rows')r where r->>'id'=x->>'reviewed';
 perform reporting_test.ok(row#>>'{observation,status}'='REVIEWED' and (row#>>'{lean_evidence,reviewed_scrap_kg}')::numeric>0,'reviewed Scrap explicit');
 perform reporting_test.ok(row#>>'{lean_evidence,version}'='2' and row#>>'{lean_evidence,comparison_status}'='NOT_CALCULATED','new relationship contract version without invented comparison');
 perform reporting_test.ok((select bool_and(evidence->>'version'='1') from public.lean_saved_comparisons where factory_id=f),'saved v1 not rewritten');
 s:=public.production_history(f,q||'{"mode":"summary","time_basis":"production"}');
 perform reporting_test.ok(jsonb_array_length(s->'rows')=1,'one dated Product line unit group');
 perform reporting_test.ok((s#>>'{rows,0,good}')::numeric=(select sum(effective_good) from public.production_entries where factory_id=f),'current Good once, not corrections twice');
 perform reporting_test.ok((s#>>'{rows,0,scrap_kg}')::numeric=(select sum(effective_scrap_kg) from public.production_entries where factory_id=f),'Scrap KG separate');
 select r into row from jsonb_array_elements(h->'rows')r where (r->>'correction_count')::int>0 limit 1;
 perform reporting_test.ok(row is not null and (row->>'original_good')::numeric>(row->>'good')::numeric,'original versus corrected Good');
 c:=public.production_history(f,q||jsonb_build_object('mode','corrections','entry',row->>'id','page_size',1));
 perform reporting_test.ok((c->>'total')::int>0 and c#>>'{rows,0,created_by}' is not null and c#>>'{rows,0,created_at}' is not null,'paged correction actor/time');
 perform reporting_test.ok(c#>>'{rows,0,previous_occurrence_key}' is not null and c#>>'{rows,0,corrected_occurrence_key}' is not null,'correction attribution relationships');
 q:=q||'{"page_size":2}';c:=null;
 loop h:=public.production_history(f,q||case when c is null then '{}' else jsonb_build_object('cursor',c) end);
  for v in select * from jsonb_array_elements(h->'rows') loop
   perform reporting_test.ok(not (v->>'id')::uuid=any(seen),'unique history page row');seen:=array_append(seen,(v->>'id')::uuid);
  end loop;n:=n+1;exit when (h->>'complete')::boolean;c:=h->'next_cursor';
 end loop;
 perform reporting_test.ok(cardinality(seen)=(select count(*) from public.production_entries where factory_id=f) and n>1,'keyset reaches entire history');
 c:=(public.production_history(f,q))->'next_cursor';
 update public.products set name=name||' renamed' where factory_id=f and id=(x->>'product')::uuid;
 perform reporting_test.fails(format('select public.production_history(%L,%L)',f,q||jsonb_build_object('cursor',c)),'40001');
 perform reporting_test.fails(format('select public.production_history(%L,%L)',f,q||jsonb_build_object('cursor',c||'{"after":"forged","source_revision":-1}')),'40001');
 perform reporting_test.fails(format('select public.production_history(%L,%L)',f,q||'{"unexpected":true}'),'22023');
 perform reporting_test.fails(format('select public.production_history(%L,%L)',f,q||'{"page_size":101}'),'22023');
 perform reporting_test.fails(format('select public.production_history(%L,%L)',f,q||'{"from_at":"2025-01-01T00:00:00Z","to_at":"2026-10-01T00:00:00Z"}'),'22023');
 before_digest:=reporting_test.digest();perform public.production_history(f,q);perform public.production_history(f,q||'{"mode":"summary"}');
 perform reporting_test.ok(reporting_test.digest()=before_digest,'readers have no operational/audit side effects');
 perform reporting_test.ok((select bool_and(not enabled) from private.production_recording_v3_activation),'readers never activate');
end$$;
-- Actual READ ONLY transaction under the authenticated database role.
select set_config('request.jwt.claim.sub',(select x->>'owner' from reporting_test.context),false);
begin read only;set local role authenticated;
select public.production_history((current_setting('request.jwt.claim.sub'))::uuid,'{}') where false;
select public.production_history((select factory_id from public.memberships where user_id=auth.uid() and is_owner limit 1),'{"reporting_version":3}')->>'contract_version';
rollback;
select count(*) as reporting_assertions from reporting_test.checks;
